from collections import deque

class Solution:

	def max_of_subarrays(self, arr, n, k):
		result = []
		window = deque()
		for i in range(k):
			while window and arr[i] >= arr[window[-1]]:
				window.pop()
			window.append(i)
		for i in range(k, n):
			result.append(arr[window[0]])
			while window and window[0] <= i - k:
				window.popleft()
			while window and arr[i] >= arr[window[-1]]:
				window.pop()
			window.append(i)
		result.append(arr[window[0]])
		return result

class Fenwick:

	def __init__(self, size):
		self.size = size
		self.tree = [0] * (size + 1)

	def add(self, idx, val):
		idx = int(idx)
		while idx <= self.size:
			self.tree[idx] += val
			idx += idx & -idx

	def sum(self, idx):
		ret = 0
		idx = int(idx)
		while idx > 0:
			ret += self.tree[idx]
			idx -= idx & -idx
		return ret
