class Solution:

	def numberOfSubarrays(self, nums: List[int], k: int) -> int:
		l = [0] * (len(nums) + 1)
		for (i, n) in enumerate(nums):
			l[i + 1] = l[i] + n % 2
		c = Counter(l)
		return sum((c[x - k] * c[x] for x in c))

class Solution:

	def numberOfSubarrays(self, nums: List[int], k: int) -> int:
		prefix = {0: 1}
		count = 0
		result_count = 0
		for num in nums:
			if num % 2:
				count += 1
			prefix[count] = prefix.get(count, 0) + 1
			result_count += prefix.get(count - k, 0)
		return result_count

