from collections import Counter, defaultdict, deque

class SegmentTree:

	def __init__(self, data, default=0, func=max):
		self._default = default
		self._func = func
		self._len = len(data)
		self._size = _size = 1 << (self._len - 1).bit_length()
		self.data = [default] * (2 * _size)
		self.data[_size:_size + self._len] = data
		for i in reversed(range(_size)):
			self.data[i] = func(self.data[i + i], self.data[i + i + 1])

	def __delitem__(self, idx):
		self[idx] = self._default

	def __getitem__(self, idx):
		return self.data[idx + self._size]

	def __setitem__(self, idx, value):
		idx += self._size
		self.data[idx] = value
		idx >>= 1
		while idx:
			self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1])
			idx >>= 1

	def __len__(self):
		return self._len

	def query(self, start, stop):
		start += self._size
		stop += self._size
		res_left = res_right = self._default
		while start < stop:
			if start & 1:
				res_left = self._func(res_left, self.data[start])
				start += 1
			if stop & 1:
				stop -= 1
				res_right = self._func(self.data[stop], res_right)
			start >>= 1
			stop >>= 1
		return self._func(res_left, res_right)

	def __repr__(self):
		return 'SegmentTree({0})'.format(self.data)

def merge(x, y):
	(xClose, xFull, xOpen) = x
	(yClose, yFull, yOpen) = y
	if xOpen == yClose:
		if xOpen:
			ret = (xClose, xFull + 1 + yFull, yOpen)
		else:
			ret = (xClose, xFull + yFull, yOpen)
	elif xOpen > yClose:
		ret = (xClose, xFull, xOpen - yClose + yOpen)
	elif xOpen < yClose:
		ret = (xClose + yClose - xOpen, yFull, yOpen)
	return ret

def solve(N, segments):
	endpoints = []
	for (i, (l, r)) in enumerate(segments):
		endpoints.append((l, 0, i))
		endpoints.append((r, 1, i))
	endpoints.sort()
	data = []
	idToIndices = defaultdict(list)
	for (x, kind, segmentId) in endpoints:
		if kind == 0:
			data.append((0, 0, 1))
		else:
			assert kind == 1
			data.append((1, 0, 0))
		idToIndices[segmentId].append(len(data) - 1)
	assert len(data) == 2 * N
	segTree = SegmentTree(data, (0, 0, 0), merge)
	best = 0
	for (k, indices) in idToIndices.items():
		assert len(indices) == 2
		removed = []
		for i in indices:
			removed.append(segTree[i])
			segTree[i] = (0, 0, 0)
		res = segTree.query(0, 2 * N)
		assert res[0] == 0
		assert res[2] == 0
		best = max(best, res[1])
		for (i, old) in zip(indices, removed):
			segTree[i] = old
	return best
