class Solution:

	def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
		heap = []
		ans = -10001
		for (i, num) in enumerate(nums):
			while len(heap) > 0:
				(_, val, idx) = heap[0]
				if idx < i - k:
					heappop(heap)
				else:
					new_val = max(num, val + num)
					ans = max(ans, new_val)
					heappush(heap, (-new_val, new_val, i))
					break
