from typing import List

class Solution:

	def findPairsWithGivenSum(self, target: int, head: Optional['Node']) -> List[List[int]]:
		high = head
		low = head
		temp = []
		while high.next != None:
			high = high.next
		while low.data < high.data:
			sum = low.data + high.data
			if sum > target:
				high = high.prev
			elif sum < target:
				low = low.next
			else:
				temp.append([low.data, high.data])
				low = low.next
				high = high.prev
		return temp

