		iMirror = 2 * C - i
		if R > i:
			LPS[i] = min(R - i, LPS[iMirror])
		else:
			LPS[i] = 0
		try:
			while string[i + 1 + LPS[i]] == string[i - 1 - LPS[i]]:
				LPS[i] += 1
		except:
