def gcd(l):
	if len(l) == 0:
		return 0
	if len(l) == 1:
		return l[0]
	if len(l) == 2:
		if l[1] == 0:
			return l[0]
		return gcd([l[1], l[0] % l[1]])
	return gcd([gcd(l[:-1]), l[-1]])

