def balance(s, x, typ, count):
	l = len(x)
	if l == typ:
		y = [i - count for i in x]
		y = [_ for _ in y if _ > 0]
		return sum(y)
	if l < typ:
		d = typ - l
		x.extend([0] * d)
		return balance(s, x, typ, count)
	if l > typ:
		y = sum(x[typ:])
