def moves(le, freq, m, n):
	avg = le / n
	mov = 0
	if n == m:
		for x in freq:
			if x <= avg:
				break
			mov += x - avg
	elif n < m:
		for i in range(n):
			mov += abs(freq[i] - avg)
		for i in range(n, m, 1):
			mov += freq[i]
		mov = int(mov)
		mov >>= 1
	else:
		for i in range(len(freq)):
			mov += abs(freq[i] - avg)
		mov += (n - m) * avg
		mov = int(mov)
		mov >>= 1
	return mov
