class SegmentTree:

	def __init__(self, arr):
		self.N = len(arr)
		self.st = [(inf, inf) for _ in range(2 * self.N)]
		for (i, v) in enumerate(arr):
			self.st[i + self.N] = arr[i]
		for i in range(self.N - 1, 0, -1):
			self.st[i] = min(self.st[i << 1], self.st[i << 1 | 1])

	def query(self, left, right):
		result = (inf, inf)
		left += self.N
		right += self.N
		while left < right:
			if left & 1:
				result = min(result, self.st[left])
				left += 1
			if right & 1:
				right -= 1
				result = min(result, self.st[right])
			left >>= 1
			right >>= 1
		return result[1]

class Tree:

	def __init__(self, root, adj):
		self.root = root
		self.euler = [(inf, inf) for _ in range(2 * len(adj))]
		self.euler_start = [0 for _ in adj]
		self.dfs(root, -1, 0, adj)
		self.st = SegmentTree(self.euler)

	def dfs(self, node, parent, height, adj):
		self.euler_start[node] = len(self.euler)
		self.euler.append((height, node))
		for neighbor in adj[node]:
			if neighbor != parent:
				self.dfs(neighbor, node, height + 1, adj)
				self.euler.append((height, node))

	def query_lca(self, u, v):
		(left, right) = (self.euler_start[u], self.euler_start[v])
		if left > right:
			(left, right) = (right, left)
		return self.st.query(left, right + 1)
