def group(S, k):
	if k == 1:
		return sum(S)
	firstPiece = 0
	answer = 0
	dynamic = {}
	for i in range(len(S) - k + 1):
		firstPiece += S[i]
		answer = max(groupWithPattern(S[i + 1:], k - 1, firstPiece, dynamic), answer)
	return answer

def groupWithPattern(S, k, p, dynamic):
	if k == 1:
		return sum(S) & p
	try:
		return dynamic[len(S), k, p]
	except KeyError:
		pass
	firstPiece = 0
	answer = 0
	for i in range(len(S) - k + 1):
		firstPiece += S[i]
		answer = max(groupWithPattern(S[i + 1:], k - 1, p & firstPiece, dynamic), answer)
	dynamic[len(S), k, p] = answer
	return answer
