class Solution:

	def diagonal(self, root):
		ans = []
		d = defaultdict(list)

		def solve(root, l):
			if root.left == None and root.right == None:
				d[l].append(root.data)
				return
			if root.left:
				solve(root.left, l - 1)
			d[l].append(root.data)
