class Solution:

	def numTrees(self, N):
		import math

		def GCD(a, b):
			if b == 0:
				return a
			else:
				return GCD(b, a % b)

		def nCr(n, r):
			if n - r < r:
				r = n - r
			(ne, de) = (1, 1)
			while r:
				ne = ne * n
				de = de * r
				val = math.gcd(ne, de)
				ne = ne // val
				de = de // val
				n -= 1
				r -= 1
			return ne
		return nCr(2 * N, N) // (N + 1) % 1000000007

